        assertTrue(body.contains("\"amountPaid\":0.00"), body);
        assertTrue(body.contains("\"total\":249.90"), body);
        assertTrue(body.contains("\"refund\":null"), body);
        assertTrue(body.contains("\"checkIn\":\"2027-03-10\""), body);
    }

